import ipaddress
from urllib.parse import urlparse

FAKE_DNS = {"evil.example": "10.0.0.5", "example.org": "93.184.216.34"}

def naive_ok(url):
    # String blocklist: easy to bypass
    return "127.0.0.1" not in url and "localhost" not in url

def to_ip(host):
    try:
        return ipaddress.ip_address(int(host, 0))   # 2130706433, 0x7f000001
    except ValueError:
        pass
    try:
        return ipaddress.ip_address(host)
    except ValueError:
        return ipaddress.ip_address(FAKE_DNS[host])  # pretend DNS lookup

def safe_ok(url):
    p = urlparse(url)
    if p.scheme not in ("http", "https"):
        return False
    ip = to_ip(p.hostname)
    # Reject loopback, private, link-local (169.254.x.x) and similar
    return ip.is_global

urls = ["http://example.org/x", "http://127.0.0.1/admin",
        "http://2130706433/admin", "http://0x7f000001/admin",
        "http://169.254.169.254/latest/meta-data", "http://evil.example/",
        "file:///etc/passwd"]
for u in urls:
    print(f"{u:42} naive={naive_ok(u)!s:5} safe={safe_ok(u)}")
